#!/usr/bin/env bash
# Full verification gate: TypeScript typecheck + the Node built-in test suite.
# Run from the repo root:  ./scripts/check.sh   (or: npm run check)
set -euo pipefail
cd "$(dirname "$0")/.."

echo "==> Typechecking (tsc --noEmit)"
npx tsc --noEmit

echo "==> Running tests (node:test via tsx)"
