import { test } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import {
  checkRateLimit,
  resetRateLimit,
  loginRateLimit,
} from "../lib/rate-limit.ts";

const opts = { max: 3, windowMs: 60_000 };

test("checkRateLimit allows up to max hits then blocks", () => {
  const key = `t:${randomUUID()}`;
  const r1 = checkRateLimit(key, opts);
  const r2 = checkRateLimit(key, opts);
  const r3 = checkRateLimit(key, opts);
  const r4 = checkRateLimit(key, opts);

  assert.equal(r1.ok, true);
  assert.equal(r2.ok, true);
  assert.equal(r3.ok, true);
  assert.equal(r4.ok, false, "the 4th hit within the window is blocked");
});

test("remaining counts down and hits zero at the limit", () => {
  const key = `t:${randomUUID()}`;
  assert.equal(checkRateLimit(key, opts).remaining, 2);
  assert.equal(checkRateLimit(key, opts).remaining, 1);
  assert.equal(checkRateLimit(key, opts).remaining, 0);
});

test("a blocked result surfaces a positive retryAfterSec", () => {
  const key = `t:${randomUUID()}`;
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  const blocked = checkRateLimit(key, opts);
  assert.equal(blocked.ok, false);
  assert.ok(blocked.retryAfterSec >= 1);
  assert.ok(blocked.retryAfterSec <= 60);
});

test("resetRateLimit clears the window for a key", () => {
  const key = `t:${randomUUID()}`;
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  checkRateLimit(key, opts);
  assert.equal(checkRateLimit(key, opts).ok, false);
  resetRateLimit(key);
  // After reset the key is fresh again.
  assert.equal(checkRateLimit(key, opts).ok, true);
});

test("separate keys are throttled independently", () => {
  const a = `t:${randomUUID()}`;
  const b = `t:${randomUUID()}`;
  checkRateLimit(a, opts);
  checkRateLimit(a, opts);
  checkRateLimit(a, opts);
  assert.equal(checkRateLimit(a, opts).ok, false);
  // b is untouched
  assert.equal(checkRateLimit(b, opts).ok, true);
});

test("loginRateLimit preset allows 5 attempts then blocks", () => {
  const id = randomUUID();
  for (let i = 0; i < 5; i++) {
    assert.equal(loginRateLimit(id).ok, true, `attempt ${i + 1} should be allowed`);
  }
  assert.equal(loginRateLimit(id).ok, false, "6th login attempt is blocked");
});

/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  { months: 12, label: "Annual", short: "1 yr", discountPct: 10 },
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 15 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 20 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/** Total charge (cents) for a plan over a term, discount applied. */
export function vpsTermPriceCents(monthlyCents: number, months: number): number {
  const t = vpsTerm(months);
  return Math.round(monthlyCents * months * (1 - t.discountPct / 100));
}

/** Effective monthly-equivalent price after the term discount (for "$/mo" display). */
export function vpsEffectiveMonthly(monthlyCents: number, months: number): number {
  return Math.round(vpsTermPriceCents(monthlyCents, months) / months);
}

export type DomainTerm = { years: number; label: string; discountPct: number };

export const DOMAIN_TERMS: DomainTerm[] = [
  { years: 1, label: "1 year", discountPct: 0 },
  { years: 2, label: "2 years", discountPct: 5 },
  { years: 3, label: "3 years", discountPct: 10 },
];

export function domainTerm(years: number): DomainTerm {
  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
}

/** Total charge (cents) for a domain over N years, discount applied. */
export function domainTermPriceCents(perYearCents: number, years: number): number {
  const t = domainTerm(years);
  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
}

/** Add whole months to a date (UTC-safe enough for billing windows). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from);
  d.setMonth(d.getMonth() + months);
  return d;
}
=========== promotions.ts ===========
/**
 * Seasonal / promotional pricing — HONEST intro-discount model.
 *
 * The whole design is an INTRO DISCOUNT: a promo discounts a customer's FIRST
 * TERM only. The "regular" (strikethrough) price is the genuine renewal price;
 * the "promo" price is the genuine first-term price. BOTH are real charges —
 * never a fabricated former price and never a bait-and-switch. The discounted
 * price shown must equal what checkout charges (see promoPriceCents usage in
 * lib/order.ts, lib/actions.ts and lib/actions-email-hosting.ts). Renewal paths
 * (worker/billing.ts, worker/product-renewals.ts) are left untouched, so
 * renewals bill the regular price — exactly what the strikethrough promises.
 *
 * Countdowns use promoEndsAt(), which returns the promo window's REAL close
 * date. Promos genuinely rotate by calendar date; a new one may begin after the
 * current one ends, but the current one truly ends when the timer says.
 *
 * Pure & deterministic: every helper takes `now` as a parameter. Nothing here
 * calls Date.now() at module load, so it is safe to import anywhere (including
 * server components that render it at request time).
 */

export type Promo = {
  id: string;
  /** Full name, e.g. "Summer Sale". */
  name: string;
  /** Short badge text, e.g. "Summer Sale". */
  label: string;
  /** Percent off the FIRST-term charge (0–100). */
  discountPercent: number;
  /** Window open, inclusive, "MM-DD". */
  start: string;
  /** Window close, inclusive, "MM-DD" (may wrap the year end). */
  end: string;
};

/**
 * Rotating seasonal promos. Checked in array order; the first promo whose
 * calendar window covers `now` wins. Windows are real dates — the countdown a
 * customer sees is the true close of the active window.
 */
export const SEASONAL_PROMOS: Promo[] = [
  { id: "new-year",       name: "New Year Sale",       label: "New Year Sale",   discountPercent: 30, start: "01-01", end: "01-07" },
  { id: "valentines",     name: "Valentine's Sale",    label: "Valentine's Sale", discountPercent: 20, start: "02-08", end: "02-16" },
  { id: "spring",         name: "Spring Sale",         label: "Spring Sale",     discountPercent: 25, start: "03-20", end: "04-05" },
  { id: "summer",         name: "Summer Sale",         label: "Summer Sale",     discountPercent: 30, start: "06-21", end: "08-10" },
  { id: "back-to-school", name: "Back-to-School Sale", label: "Back-to-School",  discountPercent: 25, start: "08-15", end: "09-15" },
  { id: "halloween",      name: "Halloween Sale",      label: "Halloween Sale",  discountPercent: 25, start: "10-24", end: "10-31" },
  { id: "black-friday",   name: "Black Friday",        label: "Black Friday",    discountPercent: 40, start: "11-24", end: "11-30" },
  { id: "cyber-monday",   name: "Cyber Monday",        label: "Cyber Monday",    discountPercent: 45, start: "12-01", end: "12-02" },
  { id: "holiday",        name: "Holiday Sale",        label: "Holiday Sale",    discountPercent: 35, start: "12-15", end: "12-31" },
];

/**
 * Always-on modest fallback so there is ALWAYS an active promo between seasons.
 * Its real end date is the start of the next seasonal promo (see promoEndsAt) —
 * an honest "the Launch Sale runs until the next sale begins".
 */
export const LAUNCH_SALE: Promo = {
  id: "launch",
  name: "Launch Sale",
  label: "Launch Sale",
  discountPercent: 15,
  start: "01-01",
  end: "12-31",
};

/** Build a concrete Date for a given year + "MM-DD" (local time). */
function dateAt(year: number, mmdd: string, endOfDay: boolean): Date {
  const [m, d] = mmdd.split("-").map(Number);
  return endOfDay
    ? new Date(year, m - 1, d, 23, 59, 59, 999)
    : new Date(year, m - 1, d, 0, 0, 0, 0);
}

/**
 * Resolve a promo's window to the concrete [start, end] occurrence around `now`,
 * correctly handling a window that wraps the year boundary (e.g. 12-28..01-03).
 */
function windowBounds(now: Date, promo: Promo): { start: Date; end: Date } {
  const y = now.getFullYear();
  let start = dateAt(y, promo.start, false);
  let end = dateAt(y, promo.end, true);
  if (end < start) {
    // Wrapping window: pick the occurrence that surrounds `now`.
    if (now >= start) end = dateAt(y + 1, promo.end, true); // December side
    else start = dateAt(y - 1, promo.start, false); // January side
  }
  return { start, end };
}

function inWindow(now: Date, promo: Promo): boolean {
  const { start, end } = windowBounds(now, promo);
  return now >= start && now <= end;
}

/** Earliest upcoming seasonal-promo start strictly after `now`. */
function nextSeasonalStart(now: Date): Date {
  const y = now.getFullYear();
  let best: Date | null = null;
  for (const p of SEASONAL_PROMOS) {
    // Consider this year's and next year's occurrence so year-end wraps around.
    for (const yr of [y, y + 1]) {
      const s = dateAt(yr, p.start, false);
      if (s > now && (!best || s < best)) best = s;
    }
  }
  return best ?? dateAt(y + 1, SEASONAL_PROMOS[0].start, false);
}

/**
 * The active promo for `now`: the first seasonal promo whose window covers it,
 * or the always-on Launch Sale fallback. Never returns null — there is always a
 * genuine, honest promo running.
 */
export function currentPromo(now: Date): Promo {
  for (const p of SEASONAL_PROMOS) {
    if (inWindow(now, p)) return p;
  }
  return LAUNCH_SALE;
}

/**
 * The genuine first-term price for a regular price under `promo`.
 * round(regularCents * (1 - discountPercent/100)). This exact value is what
 * checkout charges for the first term — display it verbatim.
 */
export function promoPriceCents(regularCents: number, promo: Promo): number {
  return Math.round(regularCents * (1 - promo.discountPercent / 100));
}

/**
 * The REAL Date the current promo window closes (drives the countdown).
 *  - A seasonal promo: the end instant of its active window.
 *  - The Launch Sale fallback: genuinely ends when the next seasonal promo
 *    begins (the next sale takes over), so the countdown is truthful.
 */
export function promoEndsAt(now: Date, promo: Promo): Date {
  if (promo.id === LAUNCH_SALE.id) return nextSeasonalStart(now);
  return windowBounds(now, promo).end;
}

// Pure, dependency-free proration maths shared by the server actions (resize,
// disk expansion, downgrade) and the client pickers that DISPLAY the number.
// No server-only imports, exactly like lib/wallet-split.ts — so the figure the
// customer sees is byte-for-byte the figure that gets charged or credited.

import { vpsEffectiveMonthly } from "./billing-terms";
import { currentPromo, promoPriceCents, type Promo } from "./promotions";

/** Average calendar month in ms (365.25/12 ≈ 30.44d). */
export const MS_PER_AVG_MONTH = 30.44 * 86400_000;

/**
 * Months left on a term, clamped to something sane.
 *
 * The clamp matters on the CREDIT side: `renewNow` can stack `expiresAt` many
 * terms into the future, and an unclamped credit multiplies the monthly delta by
 * every stacked month. The client estimate already clamped to one term while the
 * server did not, so the two disagreed and the server was the generous one.
 */
export function remainingMonths(expiresAt: Date | null, now: number, capMonths?: number): number {
  if (!expiresAt) return 0;
  const raw = Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
  return capMonths && capMonths > 0 ? Math.min(raw, capMonths) : raw;
}

/**
 * The prorated difference between two monthly plan prices over the remaining
 * term, priced the way a FRESH order for the same product would be priced today.
 *
 * Why this exists (2026-07-25): proration used the raw list monthly delta while
 * the original purchase applied BOTH the term discount (lib/order.ts) and the
 * seasonal promo. Upgrading therefore cost far more than buying the target plan
 * outright for the same end date — on a 36-month term with a 30% promo running,
 * $1,044.45 to upgrade versus $665.08 fresh: the customer overpaid $379.37. The
 * mirror image was worse in kind though not yet reachable: the downgrade CREDIT
 * used the same undiscounted delta, so it refunded more than was ever paid — a
 * self-service money printer the moment the plan catalogue allows a downgrade.
 *
 * Both directions now price off the SAME function, so they cannot drift apart:
 *   effective monthly (term discount applied) → promo applied → × months left.
 *
 * `promo` is injected so a caller can price against a specific promo; it defaults
 * to whatever is running now, which is what a fresh order today would pay.
 */
export function prorateDeltaCents(opts: {
  fromMonthlyCents: number;
  toMonthlyCents: number;
  termMonths: number;
  monthsRemaining: number;
  promo?: Promo;
  now?: Date;
}): number {
  const promo = opts.promo ?? currentPromo(opts.now ?? new Date());
  const eff = (monthly: number) =>
    promoPriceCents(vpsEffectiveMonthly(monthly, opts.termMonths), promo);
  const delta = eff(opts.toMonthlyCents) - eff(opts.fromMonthlyCents);
  return Math.round(delta * Math.max(0, opts.monthsRemaining));
}

/** Upgrade charge — never negative. */
export function prorateUpgradeCents(opts: Parameters<typeof prorateDeltaCents>[0]): number {
  return Math.max(0, prorateDeltaCents(opts));
}

/** Downgrade credit — never negative; caller passes from=old, to=new. */
export function prorateDowngradeCreditCents(
  opts: Parameters<typeof prorateDeltaCents>[0]
): number {
  return Math.max(0, -prorateDeltaCents(opts));
}
