// Pure, dependency-free wallet/card split math shared by the client wizards
// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
// resizeServer). Keeping it here — with NO server-only imports — guarantees the
// split the customer SEES is byte-for-byte the split that gets CHARGED.

/**
 * Stripe rejects card charges under ~$0.50. We never send a card amount below
 * this; when the natural remainder would fall under it we leave exactly this
 * much on the card and apply slightly less wallet credit (see walletSplit).
 */
export const STRIPE_MIN_CENTS = 50;

export type WalletSplit = {
  /** Cents taken from the customer's existing wallet balance. */
  walletApplied: number;
  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
  cardCents: number;
  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
  clampedForStripeMin: boolean;
};

/**
 * Split a due amount between the wallet and the card, honoring the customer's
 * "apply my balance" toggle and Stripe's minimum-charge floor.
 *
 * - `useWallet` off  → everything on the card.
 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS and the wallet can't cover
 *   the whole thing, reduce walletApplied so exactly STRIPE_MIN_CENTS lands on the
 *   card (never send Stripe a sub-minimum charge). Integer-cent exact throughout.
 */
export function walletSplit(opts: {
  dueCents: number;
  balanceCents: number;
  useWallet: boolean;
}): WalletSplit {
  const dueCents = Math.max(0, Math.round(opts.dueCents));
  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
  if (dueCents <= 0) return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false };

  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
  let cardCents = dueCents - walletApplied;
  let clampedForStripeMin = false;

  // A tiny non-zero card remainder that Stripe would reject. This only happens
  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
  // touch less wallet. Guarded so walletApplied can never go negative.
  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS && dueCents >= STRIPE_MIN_CENTS) {
    walletApplied = dueCents - STRIPE_MIN_CENTS;
    cardCents = STRIPE_MIN_CENTS;
    clampedForStripeMin = true;
  }
  return { walletApplied, cardCents, clampedForStripeMin };
}

// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
// checkout can provision immediately. Plain server module (not "use server").
import { z } from "zod";
import type { User } from "@prisma/client";
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { capacityCheck, diskCapacityCheck } from "./capacity";
import { invoiceCreateData } from "./invoices";
import { maybeRewardReferral } from "./actions-growth";
import { currentPromo, promoPriceCents } from "./promotions";
import { extraDiskPerGbCents } from "./disk-expand";
import {
  EXTRA_DISK_MAX_ADD_GB,
  EXTRA_DISK_MAX_TOTAL_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskLabel,
  normalizeExtraDiskGB,
} from "./extra-disk";

export class OrderError extends Error {}

export const orderSchema = z.object({
  planId: z.string().min(1),
  osTemplateId: z.string().min(1),
  hostname: z
    .string()
    .min(3)
    .max(40)
    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
  // Deploy-time extra-disk upsell. Coerced + step-normalized by
  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
});

export type OrderIntent = {
  planId: string;
  osTemplateId: string;
  hostname: string;
  nodeId?: string;
  addonMalware?: boolean;
  addonBackup?: boolean;
  addonDocker?: boolean;
  termMonths?: number;
  dedicatedIp?: boolean;
  sshPublicKey?: string;
  sshKeyName?: string;
  free?: boolean;
  /**
   * Extra root-disk GB bought at deploy time, ON TOP of the plan's diskGB. The VM
   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
   * post-deploy expansion job is needed. Permanent — never shrinks.
   */
  extraDiskGB?: number;
};

/** Extract a plain OrderIntent from a deploy form. */
export function intentFromFormData(formData: FormData): OrderIntent {
  return {
    planId: String(formData.get("planId") ?? ""),
    osTemplateId: String(formData.get("osTemplateId") ?? ""),
    hostname: String(formData.get("hostname") ?? ""),
    nodeId: String(formData.get("nodeId") ?? "") || undefined,
    addonMalware: formData.get("addon_malware") === "1",
    addonBackup: formData.get("addon_backup") === "1",
    addonDocker: formData.get("addon_docker") === "1",
    termMonths: Number(formData.get("termMonths") ?? 1),
    dedicatedIp: formData.get("dedicatedIp") === "1",
    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
    free: formData.get("free") === "1",
    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
    // bought so it drops out of JSON.stringify: the intent is round-tripped
    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
    // createOrderCheckout), and every byte of headroom matters there.
    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
  };
}

/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      return { node: n, free: n.capacityRamMB - used };
    }),
  );
  loads.sort((a, b) => b.free - a.free);
  return loads[0].node;
}

/** Validate + price an order without placing it. Throws OrderError on any problem. */
export async function orderQuote(intent: OrderIntent) {
  const parsed = orderSchema.safeParse(intent);
  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
    throw new OrderError(
      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
    );
  }
  const term = vpsTerm(Number(intent.termMonths ?? 1));
  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;

  // Extra root disk, priced per GB/month and multiplied over the term exactly
  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
  // promo — the customer pays the same $/GB whichever term they pick, and renews
  // at the same rate). Growth is one-way: this is permanent for the server.
  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
  const extraDiskCents = extraDiskMonthlyCents * term.months;
  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
  }

  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
  // real renewal price and this discounted value is the real first-term price.
  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
  // (Dedicated IP is billed at full price; the promo only touches the plan.)
  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);
  const promo = currentPromo(new Date());
  const planFirstTermCents = promoPriceCents(regularPlanCents, promo);
  const chargeCents = planFirstTermCents + ipCents + extraDiskCents;
  return {
    plan,
    os,
    term,
    chargeCents,
    promo,
    regularPlanCents,
    extraDiskGB,
    extraDiskMonthlyCents,
    extraDiskCents,
  };
}

/**
 * Place an order: validate, charge the wallet (unless a free admin grant),
 * create the Server + PROVISION job. Returns the new server id. Does NOT
 * redirect. Callers must ensure funds exist (or pass free) — this still
 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
 */
export async function placeOrder(user: User, intent: OrderIntent): Promise<string> {
  const { plan, os, term, chargeCents, promo, extraDiskGB, extraDiskMonthlyCents, extraDiskCents } =
    await orderQuote(intent);
  // Note the intro discount on the billing document (first term only; renews full).
  const promoNote = promo.discountPercent > 0 ? ` · ${promo.name} ${promo.discountPercent}% off first term` : "";

  const cap = await capacityCheck(plan.id);
  if (!cap.ok) throw new OrderError(cap.reason);

  let nodeId: string | null = null;
  if (intent.nodeId) {
    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
    if (!n) throw new OrderError("Selected location is not available.");
    nodeId = n.id;
  } else {
    const n = await scheduleNode(plan.ramMB);
    nodeId = n?.id ?? null;
  }

  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
  if (!diskCap.ok) throw new OrderError(diskCap.reason);

  const addons = {
    malwareScanner: !!intent.addonMalware,
    dailyBackup: !!intent.addonBackup,
    docker: !!intent.addonDocker,
  };
  const isAdmin = user.role === "ADMIN";
  const freeRequested = !!intent.free && isAdmin;
  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");

  const newKey = (intent.sshPublicKey ?? "").trim();
  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);

  let server;
  try {
    server = await db.$transaction(async (tx) => {
      if (!freeRequested) {
        await debitWallet(tx, user.id, chargeCents);
        await tx.walletTransaction.create({
          data: {
            userId: user.id,
            amountCents: -chargeCents,
            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`,
          },
        });
        // Billing document for the charge — created inside the same debit tx so it
        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
        // Extra disk gets its OWN line so the customer can see exactly what the
        // permanent storage costs; the lines always sum back to chargeCents.
        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNote}`;
        const planLineCents = chargeCents - extraDiskCents;
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: user.id,
            description: lineDesc,
            status: "PAID",
            period: { start: new Date(), end: addMonths(new Date(), term.months) },
            lineItems: [
              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
              ...(extraDiskCents > 0
                ? [
                    {
                      description:
                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
                      qty: 1,
                      unitCents: extraDiskCents,
                      amountCents: extraDiskCents,
                    },
                  ]
                : []),
            ],
          }),
        });
      }
      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
      }
      const s = await tx.server.create({
        data: {
          name: intent.hostname,
          hostname: intent.hostname,
          userId: user.id,
          planId: plan.id,
          osTemplateId: os.id,
          nodeId,
          addons,
          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
          // storage for easy restore") and re-confirms it on the Review step, but
          // `addons.dailyBackup` was write-only: the worker declares the key and
          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
          // the Backups tab. Nothing bridged the two, so EVERY server in the live
          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
          // job was ever enqueued. A customer would discover the safety net they
          // were promised did not exist at the moment they needed it. Bridge it
          // here, at the point of sale.
          autoBackup: !!intent.addonBackup,
          backupIntervalHours: intent.addonBackup ? 24 : null,
          termMonths: term.months,
          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
          // born at its full size, with no separate expansion job.
          extraDiskGB,
          wantsDedicatedIp: !!intent.dedicatedIp,
          isFree: freeRequested,
          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
        },
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.order",
      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
    },
  });
  if (!freeRequested) {
    try {
      await maybeRewardReferral(user.id);
    } catch {
      /* non-fatal */
    }
  }
  return server.id;
}

