const GiB = 1024 ** 3;

/** Parse a human size label ("1.2G", "340M", "220 MB") into bytes. Mirrors the
 *  server's parseSizeLabel — kept local so the client never imports the ssh2-laden
 *  detection module. */
function parseSize(label: string): number {
  const m = /^([\d.]+)\s*([KMGT]?)/i.exec((label ?? "").trim());
  if (!m) return 0;
  const n = parseFloat(m[1]);
  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
  return n * (mult[m[2].toUpperCase()] ?? 1);
}

/** Adaptive size formatter: GB for ≥1 GB, else MB. */
function fmtSize(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 MB";
  const g = bytes / GiB;
  if (g >= 1) return g >= 10 ? `${g.toFixed(0)} GB` : `${g.toFixed(1)} GB`;
  const mb = bytes / (1024 * 1024);
  return `${Math.max(1, Math.round(mb))} MB`;
}

