/** Collapse arch aliases so amd64≡x86_64 and arm64≡aarch64 compare equal. */
function normArch(a: string | null | undefined): string {
  const s = (a ?? "").toLowerCase();
  if (!s) return "";
  if (["x86_64", "amd64", "x64"].includes(s)) return "x86_64";
  if (["aarch64", "arm64"].includes(s)) return "arm64";
  if (s.startsWith("armv") || s === "armhf" || s === "arm") return "arm";
  if (["i386", "i686", "x86"].includes(s)) return "x86";
  return s;
}

