/**
 * Book a real decline: advance `dunningStage`, schedule the next attempt from the
 * day-1/3/5 table and send the email that matches where the customer now is.
 *
 * The stage is CLAMPED at DUNNING_EXHAUSTED so a re-armed attempt (a new card
 * saved after the sequence ran out) that also fails cannot send a second final
 * notice or push the customer past the end of a schedule that has no more entries.
 */
async function recordDeclinedAttempt(opts: {
  server: DueServer;
  cardCents: number;
  now: Date;
  cfg: DunningConfig;
  reason: string;
}): Promise<void> {
  const { server, cardCents, now, cfg, reason } = opts;
  const prevStage = server.dunningStage;
  const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);
  const amount = fmtUsd(cardCents);
  const last4 = server.user.cardLast4 ?? "";

  console.warn(`[billing] card declined for ${server.hostname} (attempt ${newStage}): ${reason}`);

  const calendarSuspendAt = new Date(
    server.expiresAt!.getTime() + calendarSuspendDay(cfg, true) * DAY,
  );

  if (prevStage >= DUNNING_EXHAUSTED) {
    // Already out of attempts; this was the extra try granted either by the stored
    // suspension time arriving or by `retryDunningNow` after the customer saved a
    // new card. Silent — they have already had the final notice, and a second copy
    // of it would be noise.
    //
    // The schedule drops back to the plain calendar deadline (already in the past by
    // now), so this attempt CANNOT defer the suspension it precedes. When the admin
    // kill switch is off nothing will ever be suspended, so fall back to a daily
    // cadence instead — otherwise a 10-minute sweep would attempt the same declining
    // card every 10 minutes forever, which is exactly how an issuer starts blocking
    // us outright.
    await rescheduleAttempt(
      server,
      cfg.autoSuspend ? calendarSuspendAt : new Date(now.getTime() + MIN_RETRY_GAP_MS),
    );
    return;
  }

  // Where the customer is told to expect us next. While retries remain that is the
  // next attempt; once they are spent it is the ONE CLEAR DAY the final notice
  // promises — measured from this moment, not from expiry, so a sequence that ran
  // late (worker downtime) still gets its full day instead of being suspended in the
  // same pass that told the customer it was their last chance.
  const scheduledAt =
    nextRetryAt(server.expiresAt!, newStage, now) ??
    new Date(Math.max(calendarSuspendAt.getTime(), now.getTime() + DAY));
