  // never from the row we read — `suspendDueAt` honours `dunningNextAt`, so quoting
  // the pre-update value would print a day earlier than the sweep actually acts on.
  const suspendAt =
    suspendDueAt(
      { expiresAt: server.expiresAt, dunningStage: newStage, dunningNextAt: scheduledAt },
      true,
      cfg,
    ) ?? calendarSuspendAt;

  await db.server.update({
    where: { id: server.id },
    data: { dunningStage: newStage, dunningNextAt: scheduledAt },
  });
  server.dunningStage = newStage;
  server.dunningNextAt = scheduledAt;

  await db.auditLog
    .create({
      data: {
        userId: server.userId,
        action: "billing.card_declined",
        detail: `${server.id}: attempt ${newStage} for ${amount} — ${reason.slice(0, 180)}`,
      },
    })
    .catch(() => {
      /* audit is bookkeeping; never let it break collection */
    });

  if (newStage === 1) {
