  const server = await loadServer(serverId);
  if (!server) throw new ResizeError("Not found");
  const newPlan = await loadPlan(planId);
  if (!newPlan?.active) throw new ResizeError("Plan not available.");
  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
  if (newPlan.diskGB < server.plan.diskGB) {
    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
  }
  if (newPlan.priceCents < server.plan.priceCents) {
    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
