import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { vpsTermPriceCents, vpsEffectiveMonthly, VPS_TERMS } from "../lib/billing-terms.ts";
import { currentPromo, promoPriceCents, LAUNCH_SALE, type Promo } from "../lib/promotions.ts";
import { extraDiskCentsAt } from "../lib/extra-disk.ts";

/**
 * REAL INCIDENT (2026-07-25, user report): "the price said 8.99 but it only
 * charged 6.29".
 *
 * The deploy wizard displayed the REGULAR term price while lib/order.ts charged
 * the promo-discounted first-term price. Root cause: the promo math existed
 * twice — `promoPriceCents` (lib/promotions.ts) on the server and a hand-rolled
 * copy in `components/customer/DeployWizard.tsx` — so "displayed === charged"
 * held only by coincidence. The audit's words: this class of bug "would have
 * been caught by one assertion that the wizard and engine agree".
 *
 * These tests pin the composed price across every plan price x every term x
 * promo-on/promo-off, and include a tripwire on the wizard's duplicated line so
 * that editing it forces a re-check against promoPriceCents.
 *
 * Deterministic: every promo lookup takes an injected date, never Date.now().
 */

const REPO = join(import.meta.dirname, "..");

/** The live plan catalogue at the time of the incident (cents/month). */
const PLAN_MONTHLY_CENTS = [899, 1299, 2099, 3299];

/** No-promo control: the same shape as a real promo with the discount switched off. */
const NO_PROMO: Promo = { ...LAUNCH_SALE, discountPercent: 0 };
/** The promo that was running when the $8.99/$6.29 mismatch was reported. */
const SUMMER_2026 = new Date("2026-07-26T12:00:00.000Z");

/**
 * What lib/order.ts orderQuote CHARGES (lib/order.ts:135-140):
 * regular term price -> promo on the first term -> add-ons at full price.
 */
function chargedCents(monthlyCents: number, months: number, promo: Promo, addonMonthlyCents = 0): number {
  const regularPlanCents = vpsTermPriceCents(monthlyCents, months);
  return promoPriceCents(regularPlanCents, promo) + addonMonthlyCents * months;
}

/**
 * What the wizard DISPLAYS as "Due today" (components/customer/DeployWizard.tsx:96
 * + :172-177). `wizardPromoCents` is that file's own line, reproduced verbatim
 * because the component re-implements promoPriceCents instead of importing it.
 */
const wizardPromoCents = (regular: number, promoPercent: number) => Math.round(regular * (1 - promoPercent / 100));
function displayedCents(monthlyCents: number, months: number, promo: Promo, addonMonthlyCents = 0): number {
  const regularPlanTerm = vpsTermPriceCents(monthlyCents, months);
  const promoPlanTerm = wizardPromoCents(regularPlanTerm, promo.discountPercent);
  return promoPlanTerm + addonMonthlyCents * months;
}

test("the promo running on the day of the incident is the 30% Summer Sale", () => {
  const promo = currentPromo(SUMMER_2026);
  assert.equal(promo.id, "summer");
  assert.equal(promo.discountPercent, 30);
});

test("$8.99/mo monthly with the 30% promo charges exactly $6.29 — the reported numbers", () => {
  const promo = currentPromo(SUMMER_2026);
  const regular = vpsTermPriceCents(899, 1);
  assert.equal(regular, 899, "the strikethrough (renewal) price");
  assert.equal(promoPriceCents(regular, promo), 629, "the first-term price actually charged");
  // And the wizard must show that same 629 as Due today, not the 899.
  assert.equal(displayedCents(899, 1, promo), 629);
});

test("displayed price equals charged price for every plan x term x promo state", () => {
  const promos: Promo[] = [currentPromo(SUMMER_2026), NO_PROMO, { ...LAUNCH_SALE }];
  for (const monthly of PLAN_MONTHLY_CENTS) {
    for (const term of VPS_TERMS) {
      for (const promo of promos) {
        for (const addonMonthly of [0, 500, 1234]) {
          const shown = displayedCents(monthly, term.months, promo, addonMonthly);
          const charged = chargedCents(monthly, term.months, promo, addonMonthly);
          assert.equal(
            shown,
            charged,
            `plan ${monthly}c x ${term.months}mo, promo ${promo.discountPercent}%, addon ${addonMonthly}c/mo: shown ${shown} != charged ${charged}`,
          );
        }
      }
    }
  }
});

test("with the promo off, the charge is the regular term price (nothing is silently discounted)", () => {
  for (const monthly of PLAN_MONTHLY_CENTS) {
    for (const term of VPS_TERMS) {
      assert.equal(chargedCents(monthly, term.months, NO_PROMO), vpsTermPriceCents(monthly, term.months));
    }
  }
});

test("the promo never touches add-ons — dedicated IP and extra disk bill at full price", () => {
  const promo = currentPromo(SUMMER_2026);
  const ipMonthly = 400;
  const extraDiskMonthly = extraDiskCentsAt(50, 10); // 50 GB at 10c/GB/mo = 500c
  assert.equal(extraDiskMonthly, 500);
  for (const term of VPS_TERMS) {
    const withAddons = chargedCents(2099, term.months, promo, ipMonthly + extraDiskMonthly);
    const planOnly = chargedCents(2099, term.months, promo);
    assert.equal(
      withAddons - planOnly,
      (ipMonthly + extraDiskMonthly) * term.months,
      `${term.months}mo: the add-on portion must be undiscounted`,
    );
  }
});

test("term discount and promo compose in ONE order only — the other order is 3c cheaper", () => {
  // Why both call sites must share promoPriceCents(vpsTermPriceCents(...)) rather
  // than each rounding where it feels natural: applying the promo to the MONTHLY
  // price first and then the term discount gives a different total. $8.99 x 12mo
  // at -10% with a 30% promo: 6796c the canonical way, 6793c the other way. Three
  // cents is enough to make an invoice not add up.
  const promo = currentPromo(SUMMER_2026);
  const canonical = promoPriceCents(vpsTermPriceCents(899, 12), promo);
  const promoFirst = vpsTermPriceCents(promoPriceCents(899, promo), 12);
  assert.equal(canonical, 6796);
  assert.equal(promoFirst, 6793);
  assert.notEqual(canonical, promoFirst);
});

test("the per-month figure shown on a term card is derived from the charged total", () => {
  // DeployWizard.tsx:522-524 shows `promoCents(regTotal) / t.months` as "$x/mo".
  // It must be the charged total divided down, never the monthly list price with a
  // discount applied to it — otherwise 12 x the displayed /mo != the total billed.
  const promo = currentPromo(SUMMER_2026);
  for (const monthly of PLAN_MONTHLY_CENTS) {
    for (const term of VPS_TERMS) {
      const total = chargedCents(monthly, term.months, promo);
      const perMo = Math.round(total / term.months);
      assert.ok(
        Math.abs(perMo * term.months - total) <= term.months,
        `plan ${monthly}c x ${term.months}mo: /mo x months must reconstruct the total within rounding`,
      );
      // The undiscounted effective monthly is a strictly higher number: proof the
      // promo is included in what the customer is shown per month.
      if (promo.discountPercent > 0) {
        assert.ok(perMo < vpsEffectiveMonthly(monthly, term.months));
      }
    }
  }
});

/**
 * TRIPWIRE. `wizardPromoCents` above is a copy of a line that lives in a React
 * component we cannot import here (it pulls in the whole client runtime). If that
 * line changes, this copy is stale and the equivalence tests above are worthless
 * — so fail loudly and make the author re-derive it. The permanent fix is for the
 * wizard to import promoPriceCents from lib/promotions.ts (audit rec #21).
 */
test("the wizard still applies the promo to the TERM TOTAL with the same rounding", () => {
  const src = readFileSync(join(REPO, "components/customer/DeployWizard.tsx"), "utf8");
  assert.ok(
    src.includes("const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));"),
    "DeployWizard's promo line changed — re-check it against promoPriceCents in lib/promotions.ts and update this test",
  );
  assert.ok(
    src.includes("const regularPlanTerm = plan ? vpsTermPriceCents(plan.priceCents, termMonths) : 0;") &&
      src.includes("const promoPlanTerm = promoCents(regularPlanTerm);"),
    "the promo must be applied to the term TOTAL (vpsTermPriceCents), not to the monthly price",
  );
});

test("the server charge path still composes promoPriceCents(vpsTermPriceCents(...))", () => {
  const src = readFileSync(join(REPO, "lib/order.ts"), "utf8");
  assert.ok(src.includes("const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months);"));
  assert.ok(src.includes("const planFirstTermCents = promoPriceCents(regularPlanCents, promo);"));
  // Add-ons are added AFTER the promo, at full price.
  assert.ok(src.includes("const chargeCents = planFirstTermCents + ipCents + extraDiskCents;"));
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  MS_PER_AVG_MONTH,
  prorateDeltaCents,
  prorateUpgradeCents,
  prorateDowngradeCreditCents,
  remainingMonths,
} from "../lib/proration.ts";
import { vpsTermPriceCents } from "../lib/billing-terms.ts";
import { currentPromo, promoPriceCents, LAUNCH_SALE, type Promo } from "../lib/promotions.ts";

/**
 * REAL INCIDENTS — docs/QA-PRELAUNCH.md P0-6 (and its mirror image):
 *
 *  1. Upgrade proration priced the RAW list-price monthly delta while the original
 *     order applied both the term discount and the seasonal promo. On a 36-month
 *     term with the 30% Summer Sale running, upgrading Starter -> Max the day after
 *     purchase cost $1,044.45 against $665.08 for buying Max outright on the same
 *     end date: the customer overpaid $379.37.
 *  2. The downgrade CREDIT used that same undiscounted delta over an UNCLAMPED
 *     remaining term, so it refunded more than had ever been paid — a self-service
 *     money printer that was one cheap-but-storage-heavy plan away from reachable
 *     (blocked today only by the disk-monotonic guard, QA P1-14).
 *
 * Both directions now price through lib/proration.ts. These tests hold the two
 * halves against each other so they cannot drift apart again.
 *
 * Deterministic: every `now` and every promo is injected — nothing reads the clock
 * except through a value supplied by the test.
 */

/** Live plan catalogue (cents/month) at the time of the incident. */
const STARTER = 899;
const MAX = 3299;
const TERM = 36;

/** The 30% Summer Sale — the promo running when P0-6 was measured. */
const PROMO = currentPromo(new Date("2026-07-26T12:00:00.000Z"));
const NO_PROMO: Promo = { ...LAUNCH_SALE, discountPercent: 0 };

/** What a FRESH order for `monthly` over `TERM` costs today (lib/order.ts). */
const freshOrderCents = (monthly: number, promo: Promo) =>
  promoPriceCents(vpsTermPriceCents(monthly, TERM), promo);

test("the promo and catalogue this file is pinned to have not moved", () => {
  assert.equal(PROMO.discountPercent, 30);
  assert.equal(freshOrderCents(STARTER, PROMO), 18124, "Starter, 36mo, -20% term, -30% promo");
  assert.equal(freshOrderCents(MAX, PROMO), 66508, "Max, 36mo, -20% term, -30% promo");
});

test("upgrading on day one costs exactly the difference between the two fresh orders", () => {
  // The invariant P0-6 broke: an upgrade must never cost more than simply having
  // bought the target plan for the same term in the first place.
  const charge = prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    termMonths: TERM,
    monthsRemaining: TERM,
    promo: PROMO,
  });
  assert.equal(charge, 48384);
  assert.equal(
    freshOrderCents(STARTER, PROMO) + charge,
    freshOrderCents(MAX, PROMO),
    "paid-for-Starter + upgrade must equal the price of Max bought outright",
  );
});

test("a 36-month term with a promo does not reproduce the $379 overcharge", () => {
  // The old line was: monthlyDelta (raw list) x remainingMonths, with no term
  // discount and no promo. Reproduced here purely to measure the gap it created.
  const now = new Date("2026-07-27T12:00:00.000Z"); // bought yesterday
  const expiresAt = new Date("2029-07-26T12:00:00.000Z"); // 36-month term
  const months = remainingMonths(expiresAt, now.getTime());
  assert.ok(months > 35.9 && months < 36, `~36 months left, got ${months}`);

  const oldOvercharge = Math.round((MAX - STARTER) * months); // the P0-6 formula
  const nowCharge = prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    termMonths: TERM,
    monthsRemaining: months,
    promo: PROMO,
  });

  const paidTotalOld = freshOrderCents(STARTER, PROMO) + oldOvercharge;
  const paidTotalNow = freshOrderCents(STARTER, PROMO) + nowCharge;
  const fresh = freshOrderCents(MAX, PROMO);

  assert.ok(paidTotalOld - fresh > 37_000, `the old formula overcharged by ${(paidTotalOld - fresh) / 100} USD`);
  // The corrected charge tracks the fresh price to within one day of elapsed term.
  assert.ok(
    fresh - paidTotalNow >= 0 && fresh - paidTotalNow <= 100,
    `upgrade must not exceed the fresh price; gap was ${fresh - paidTotalNow}c`,
  );
});

test("an upgrade charge equals the mirror-image downgrade credit for the same pair", () => {
  // Upgrade A->B and downgrade B->A over the same remaining term must be the same
  // number of cents, or the pair creates or destroys money on every round trip.
  for (const months of [1, 3, 6, 12, 24, 36]) {
    for (const term of [1, 12, 24, 36]) {
      for (const promo of [PROMO, NO_PROMO]) {
        const up = prorateUpgradeCents({
          fromMonthlyCents: STARTER,
          toMonthlyCents: MAX,
          termMonths: term,
          monthsRemaining: months,
          promo,
        });
        const down = prorateDowngradeCreditCents({
          fromMonthlyCents: MAX,
          toMonthlyCents: STARTER,
          termMonths: term,
          monthsRemaining: months,
          promo,
        });
        assert.equal(up, down, `${term}mo term, ${months}mo left, promo ${promo.discountPercent}%`);
        assert.ok(up > 0, "the pair must actually move money, or this test proves nothing");
      }
    }
  }
});

test("a fractional remaining term is symmetric to within a cent", () => {
  // Math.round is asymmetric about zero at exactly .5 (Math.round(-2.5) === -2),
  // so the two directions may differ by one cent when delta x months lands on a
  // half cent. Bounded here so a real divergence still fails.
  for (const months of [0.5, 1.25, 7.333, 11.98, 35.9724]) {
    const up = prorateUpgradeCents({
      fromMonthlyCents: STARTER,
      toMonthlyCents: MAX,
      termMonths: TERM,
      monthsRemaining: months,
      promo: PROMO,
    });
    const down = prorateDowngradeCreditCents({
      fromMonthlyCents: MAX,
      toMonthlyCents: STARTER,
      termMonths: TERM,
      monthsRemaining: months,
      promo: PROMO,
    });
    assert.ok(Math.abs(up - down) <= 1, `${months}mo left: up ${up} vs down ${down}`);
  }
});

test("upgrade then downgrade over the same remaining term nets to zero", () => {
  const months = remainingMonths(new Date("2027-07-26T00:00:00.000Z"), new Date("2026-07-26T00:00:00.000Z").getTime());
  let wallet = 0;
  wallet -= prorateUpgradeCents({
    fromMonthlyCents: STARTER,
    toMonthlyCents: MAX,
    termMonths: 12,
    monthsRemaining: months,
    promo: PROMO,
  });
  wallet += prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: 12,
    monthsRemaining: months,
    promo: PROMO,
  });
  assert.equal(wallet, 0, "a round trip must neither cost nor pay the customer");
});

test("a downgrade credit never exceeds what the customer paid for the term", () => {
  // The money printer: credit = raw delta x UNCLAMPED remaining months. A customer
  // who stacked "Renew now" three times had expiresAt 108 months out, so the credit
  // was three terms' worth of a delta they had paid at a discount.
  const paidForMax = freshOrderCents(MAX, PROMO);
  const clamped = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: remainingMonths(new Date("2035-07-26T00:00:00.000Z"), new Date("2026-07-26T00:00:00.000Z").getTime(), TERM),
    promo: PROMO,
  });
  assert.ok(clamped <= paidForMax, `credit ${clamped} must not exceed the ${paidForMax} paid`);
  // And the customer is left having paid exactly the price of the plan they moved to.
  assert.equal(paidForMax - clamped, freshOrderCents(STARTER, PROMO));

  // Unclamped, the same downgrade would have refunded more than was ever paid.
  const unclamped = prorateDowngradeCreditCents({
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: remainingMonths(new Date("2035-07-26T00:00:00.000Z"), new Date("2026-07-26T00:00:00.000Z").getTime()),
    promo: PROMO,
  });
  assert.ok(unclamped > paidForMax, "the clamp is the only thing standing between this and free money");
});

test("remainingMonths clamps at zero and never returns a negative", () => {
  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
  assert.equal(remainingMonths(null, now), 0, "no expiry (free/admin server) => nothing to prorate");
  assert.equal(remainingMonths(new Date("2026-07-25T00:00:00.000Z"), now), 0, "already expired");
  assert.equal(remainingMonths(new Date("2020-01-01T00:00:00.000Z"), now), 0, "long expired");
  assert.equal(remainingMonths(new Date(now), now), 0, "expires exactly now");
});

test("remainingMonths honours capMonths and ignores a non-positive cap", () => {
  const now = new Date("2026-07-26T00:00:00.000Z").getTime();
  const threeTerms = new Date(now + 36 * MS_PER_AVG_MONTH);
  assert.equal(remainingMonths(threeTerms, now, 12), 12, "capped to one 12-month term");
  assert.ok(remainingMonths(threeTerms, now) > 35.9, "uncapped returns the raw remainder");
  assert.ok(remainingMonths(threeTerms, now, 0) > 35.9, "cap 0 means no cap");
  assert.ok(remainingMonths(threeTerms, now, -5) > 35.9, "a negative cap means no cap");
  // A cap larger than what is left must not inflate the remainder.
  assert.ok(remainingMonths(new Date(now + 6 * MS_PER_AVG_MONTH), now, 36) < 6.001);
});

test("neither direction can ever return a negative number of cents", () => {
  const wrongWay = {
    fromMonthlyCents: MAX,
    toMonthlyCents: STARTER,
    termMonths: TERM,
    monthsRemaining: 12,
    promo: PROMO,
  };
  assert.equal(prorateUpgradeCents(wrongWay), 0, "a 'downgrade' fed to the charge path must charge nothing");
  assert.equal(
    prorateDowngradeCreditCents({ ...wrongWay, fromMonthlyCents: STARTER, toMonthlyCents: MAX }),
    0,
    "an 'upgrade' fed to the credit path must credit nothing",
  );
  assert.equal(prorateDeltaCents({ ...wrongWay, monthsRemaining: -12 }), 0, "negative months are clamped");
  assert.equal(
    prorateDeltaCents({ fromMonthlyCents: MAX, toMonthlyCents: MAX, termMonths: TERM, monthsRemaining: 12, promo: PROMO }),
    0,
    "same plan, no delta",
  );
});

test("the promo is injectable, and defaults to the promo running at `now`", () => {
  const args = { fromMonthlyCents: STARTER, toMonthlyCents: MAX, termMonths: TERM, monthsRemaining: 12 };
  const summer = prorateUpgradeCents({ ...args, now: new Date("2026-07-26T12:00:00.000Z") });
  const explicit = prorateUpgradeCents({ ...args, promo: PROMO });
  assert.equal(summer, explicit, "the default promo for a July date is the Summer Sale");
  const undiscounted = prorateUpgradeCents({ ...args, promo: NO_PROMO });
  assert.ok(undiscounted > summer, "a promo must reduce the prorated charge, not raise it");
});

