import { test } from "node:test";
import assert from "node:assert/strict";
import { walletSplit, STRIPE_MIN_CENTS } from "../lib/wallet-split.ts";

/**
 * `walletSplit` is the one function that decides how much of a purchase comes out
 * of the wallet and how much goes to the card. It is shared by the client wizards
 * (DeployWizard, ResizePicker, AddStorage) and the server actions (payAndDeploy,
 * resizeServer, expandDisk) and by renewals (worker/billing.ts), precisely so the
 * split a customer SEES is the split that gets CHARGED — the invariant the
 * $8.99/$6.29 incident broke elsewhere.
 *
 * The three properties that matter, because breaking any of them either loses
 * money or hands Stripe a charge it will reject:
 *   1. walletApplied + cardCents === dueCents, always, exactly (integer cents).
 *   2. cardCents is 0 or >= Stripe's 50c floor (see the caveat test at the end).
 *   3. nothing is ever negative, and the wallet is never over-drawn.
 */

/** Amounts chosen to straddle every branch: zero, sub-floor, floor, real prices. */
const DUES = [0, 1, 25, 49, 50, 51, 99, 100, 149, 499, 500, 629, 899, 1299, 4999, 66508];
const BALANCES = [0, 1, 25, 49, 50, 51, 99, 100, 499, 628, 629, 900, 5000, 100000];

test("wallet + card always sums to exactly the amount due", () => {
  for (const dueCents of DUES) {
    for (const balanceCents of BALANCES) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.equal(
          s.walletApplied + s.cardCents,
          dueCents,
          `due ${dueCents}, balance ${balanceCents}, useWallet ${useWallet}`,
        );
      }
    }
  }
});

test("the card leg is never below Stripe's 50c floor unless it is zero", () => {
  for (const dueCents of DUES) {
    // NOTE the guard: walletSplit can only lift the card leg to the floor when the
    // whole amount due is itself >= the floor. Sub-floor dues are covered by the
    // dedicated caveat test at the bottom of this file.
    if (dueCents > 0 && dueCents < STRIPE_MIN_CENTS) continue;
    for (const balanceCents of BALANCES) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.ok(
          s.cardCents === 0 || s.cardCents >= STRIPE_MIN_CENTS,
          `due ${dueCents}, balance ${balanceCents}, useWallet ${useWallet} -> card ${s.cardCents}`,
        );
      }
    }
  }
});

test("nothing is ever negative and the wallet is never over-drawn", () => {
  for (const dueCents of [...DUES, -100, -1]) {
    for (const balanceCents of [...BALANCES, -50]) {
      for (const useWallet of [true, false]) {
        const s = walletSplit({ dueCents, balanceCents, useWallet });
        assert.ok(s.walletApplied >= 0, `walletApplied ${s.walletApplied}`);
        assert.ok(s.cardCents >= 0, `cardCents ${s.cardCents}`);
        assert.ok(s.walletApplied <= Math.max(0, dueCents), "never apply more wallet than is owed");
        if (useWallet) {
          assert.ok(
            s.walletApplied <= Math.max(0, balanceCents),
            `due ${dueCents}, balance ${balanceCents} -> wallet ${s.walletApplied} exceeds the balance`,
          );
        } else {
          assert.equal(s.walletApplied, 0, "wallet toggle off means no wallet is touched");
        }
      }
    }
  }
});

test("a zero due charges nothing anywhere (free/admin deploys, $0 prorations)", () => {
  for (const balanceCents of BALANCES) {
    const s = walletSplit({ dueCents: 0, balanceCents, useWallet: true });
    assert.deepEqual(s, { walletApplied: 0, cardCents: 0, clampedForStripeMin: false });
  }
});

test("a wallet that covers the whole charge means no Stripe hop at all", () => {
  const s = walletSplit({ dueCents: 629, balanceCents: 1000, useWallet: true });
  assert.deepEqual(s, { walletApplied: 629, cardCents: 0, clampedForStripeMin: false });
  // Exactly covered is still fully covered — an off-by-one here would send a $0
  // charge to Stripe and fail the deploy.
  const exact = walletSplit({ dueCents: 629, balanceCents: 629, useWallet: true });
  assert.deepEqual(exact, { walletApplied: 629, cardCents: 0, clampedForStripeMin: false });
});

test("the wallet toggle off puts the entire amount on the card", () => {
  const s = walletSplit({ dueCents: 899, balanceCents: 100000, useWallet: false });
  assert.deepEqual(s, { walletApplied: 0, cardCents: 899, clampedForStripeMin: false });
});

test("a sub-floor remainder is lifted to exactly 50c by applying less wallet credit", () => {
  // due 899, balance 880 -> the natural remainder is 19c, which Stripe rejects.
  const s = walletSplit({ dueCents: 899, balanceCents: 880, useWallet: true });
  assert.equal(s.cardCents, STRIPE_MIN_CENTS);
  assert.equal(s.walletApplied, 849);
  assert.equal(s.walletApplied + s.cardCents, 899);
  assert.equal(s.clampedForStripeMin, true, "the wizard prints a line explaining this — it must be flagged");
  // The clamp only fires when it has to: a remainder already at the floor is left alone.
  const atFloor = walletSplit({ dueCents: 899, balanceCents: 849, useWallet: true });
  assert.equal(atFloor.cardCents, 50);
  assert.equal(atFloor.clampedForStripeMin, false);
});

test("the clamp never over-draws a wallet that cannot cover the reduced amount", () => {
  // due 50, balance 45: the remainder would be 5c. Lifting the card to 50c means
  // applying ZERO wallet — never a negative amount.
  const s = walletSplit({ dueCents: 50, balanceCents: 45, useWallet: true });
  assert.deepEqual(s, { walletApplied: 0, cardCents: 50, clampedForStripeMin: true });
});

test("fractional and non-integer inputs are rounded to whole cents before splitting", () => {
  const s = walletSplit({ dueCents: 100.4, balanceCents: 30.6, useWallet: true });
  assert.equal(s.walletApplied + s.cardCents, 100, "the due is rounded once, then split exactly");
  assert.ok(Number.isInteger(s.walletApplied) && Number.isInteger(s.cardCents));
});

/**
 * KNOWN GAP, asserted so it is visible rather than surprising (reported, NOT
 * fixed here — lib/wallet-split.ts is not this change's file).
 *
 * When the amount due is itself under Stripe's 50c floor and the wallet holds
 * less than that, the card leg comes out under the floor and nothing can lift it
 * (there is no more of the charge to move). `createResizeCheckout` /
 * `createDiskExpandCheckout` (lib/stripe.ts) pass `cardCents` straight to Stripe
 * with no floor guard, unlike the off-session path which does check
 * (lib/stripe-cards.ts:523), so this surfaces as a checkout error. Reachable via
 * a tiny plan-upgrade proration late in a term with a few cents of wallet credit.
 */
test("KNOWN GAP: a sub-floor due with a partial balance yields a sub-floor card leg", () => {
  const s = walletSplit({ dueCents: 30, balanceCents: 10, useWallet: true });
  assert.equal(s.walletApplied, 10);
  assert.equal(s.cardCents, 20, "documents current behaviour: 20c cannot be charged by card");
  assert.equal(s.clampedForStripeMin, false, "and it is not even flagged to the caller");
  assert.ok(s.cardCents < STRIPE_MIN_CENTS);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  DEFAULT_PAGE_MARKERS,
  NEAR_EMPTY_BODY_BYTES,
  certCoversName,
  defaultPageReason,
  isServing,
  judgeMigrationOutcome,
  parseUnitExecPaths,
  preflightUnitExecs,
  probeBody,
  unfoldUnitLines,
  type UnitExecHost,
} from "../worker/migrate-real.ts";

/**
 * The migration verification gate — the pure decision logic that stands between
 * "the copy finished" and telling a customer their move is done. Every case here
 * is a real field incident; `worker/migrate-real.ts` names this file twice (at
 * `judgeMigrationOutcome` and at `UnitExecHost`) as the place that keeps them from
 * recurring.
 *
 * Deterministic: no SSH, no network, no clock. `preflightUnitExecs` is driven
 * through its `UnitExecHost` seam with an in-memory fake host.
 */

/* ------------------------------------------------------------------ *
 * 1. A stock web-server page is NOT the customer's site
 *    Incident 2026-07-25: the run reported the customer's main site as serving.
 *    The browser showed a cert warning and then the Apache2 Debian Default Page —
 *    apache2 had been re-enabled from the source and was answering on a port our
 *    generated nginx config was supposed to own. Every placeholder answers 200,
 *    which is why "make a request and check the status" passed for a dead site.
 * ------------------------------------------------------------------ */

const REAL_PAGE =
  "<!doctype html><html><head><title>Studio Nexis</title></head><body>" +
  "<h1>Studio Nexis</h1><p>We build things. Contact us for a quote.</p></body></html>";

test("a 200 carrying a distro default page is not 'serving'", () => {
  const apacheDebian =
    '<!DOCTYPE html><html><head><title>Apache2 Debian Default Page: It works</title></head>' +
    "<body><h1>Apache2 Debian Default Page</h1><p>This is the default welcome page…</p></body></html>";
  const reason = defaultPageReason("200", apacheDebian);
  assert.match(reason, /Apache2 Debian default page/);
  assert.match(reason, /not your site/);

  assert.match(defaultPageReason("200", "<h1>Welcome to nginx!</h1>" + "x".repeat(200)), /Welcome to nginx/);
  assert.match(
    defaultPageReason("200", "<html><body><h1>It works!</h1></body></html>"),
    /It works!/,
    "the classic /var/www/html/index.html",
  );
  assert.match(
    defaultPageReason("200", "<title>Apache HTTP Server Test Page</title>" + "y".repeat(200)),
    /stock Apache test page/,
  );
  assert.equal(DEFAULT_PAGE_MARKERS.length, 5, "five known placeholders; add a test with the sixth");
});

test("a default page split across a newline still matches (probeBody keeps newlines)", () => {
  // Regression guard on probeBody: the earlier `clean()` stripped ALL control
  // characters including newlines, gluing "Apache2 Debian Default\nPage" into
  // "DefaultPage" and making every marker unmatchable.
  const raw = "<h1>Apache2 Debian Default\nPage</h1>\x00\x07<p>default welcome</p>";
  const body = probeBody(raw);
  assert.ok(body.includes("\n"), "newlines survive");
  assert.ok(!body.includes("\x00"), "other control characters become spaces");
  assert.match(defaultPageReason("200", body), /Apache2 Debian default page/);
});

test("a real page is never flagged, even when its copy contains the words 'it works'", () => {
  assert.equal(defaultPageReason("200", REAL_PAGE), "");
  const prose = "<html><body><h2>Our process</h2><p>Tell us what you need and it works! Really.</p>" + "z".repeat(120) + "</body></html>";
  assert.equal(defaultPageReason("200", prose), "", "the marker is anchored on <h1>, not on the phrase");
});

test("an empty 200 is a dead vhost, but a short API response is not", () => {
  const empty = defaultPageReason("200", "   \n  ");
  assert.match(empty, /empty page/);
  assert.match(empty, /is not there/);
  assert.equal(defaultPageReason("200", '{"ok":true}'), "", "a JSON API answering correctly");
  assert.equal(defaultPageReason("200", "[]"), "", "a JSON array");
  assert.equal(defaultPageReason("200", '<?xml version="1.0"?><rss/>'), "", "a feed");
  assert.equal(defaultPageReason("200", "<div id=root></div>".padEnd(NEAR_EMPTY_BODY_BYTES + 1, " ")).length, 0);
});

test("content is only judged on a 2xx — a redirect or 404 already proves the vhost matched", () => {
  for (const code of ["301", "302", "401", "403", "404"]) {
    assert.equal(defaultPageReason(code, ""), "", `${code} with an empty body is not a content failure`);
    assert.equal(defaultPageReason(code, "<h1>Welcome to nginx!</h1>"), "", `${code} is not judged on content`);
  }
  assert.equal(defaultPageReason("000", ""), "", "a connection failure is handled by isServing, not here");
});

test("isServing accepts any answered status and rejects dead ports and 5xx", () => {
  for (const code of ["200", "204", "301", "302", "401", "403", "404", "418"]) {
    assert.equal(isServing(code), true, code);
  }
  for (const code of ["000", "500", "502", "503", "504", "", "abc"]) {
    assert.equal(isServing(code), false, code);
  }
});

/* ------------------------------------------------------------------ *
 * 2. Wildcard certificates cover ONE label
 *    Incident 2026-07-25: studionexis.com was served nexis.revsports.ca's
 *    certificate, so every visitor got ERR_CERT_COMMON_NAME_INVALID — and the run
 *    reported the domain as serving, because the probe used -k.
 * ------------------------------------------------------------------ */

test("*.example.com covers exactly one label — not two, and not the bare domain", () => {
  assert.equal(certCoversName(["*.example.com"], "www.example.com"), true);
  assert.equal(certCoversName(["*.example.com"], "api.example.com"), true);
  assert.equal(certCoversName(["*.example.com"], "a.b.example.com"), false, "two labels are NOT covered");
  assert.equal(certCoversName(["*.example.com"], "example.com"), false, "the apex needs its own SAN");
  assert.equal(certCoversName(["*.example.com", "example.com"], "example.com"), true);
});

test("a certificate for another site never counts as covering this one", () => {
  assert.equal(certCoversName(["nexis.revsports.ca", "*.revsports.ca"], "studionexis.com"), false);
  assert.equal(certCoversName([], "studionexis.com"), false, "no names known => not covered");
  assert.equal(certCoversName(["*.com"], "studionexis.com"), true, "single-label wildcard math is still one label");
  assert.equal(certCoversName(["*.studionexis.com"], "studionexis.com.evil.test"), false);
});

test("case and a trailing dot do not change coverage", () => {
  assert.equal(certCoversName(["studionexis.com"], "StudioNexis.COM"), true);
  assert.equal(certCoversName(["studionexis.com"], "studionexis.com."), true);
  assert.equal(certCoversName(["*.studionexis.com"], "WWW.StudioNexis.com."), true);
});

/* ------------------------------------------------------------------ *
 * 3. ExecStart parsing — field note #13, which recurred as #25
 *    nexis-next.service carried
 *      ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
 *    The source had a hand-installed Node at /usr/local/bin/node; the target has
 *    apt's at /usr/bin/node and NOTHING at /usr/local/bin/node. systemd failed the
 *    exec 203/EXEC, the unit crash-looped 78 times, and the migration reported
 *    SUCCESS.
 * ------------------------------------------------------------------ */

test("the exact unit from the incident yields its absolute interpreter path", () => {
  const unit = [
    "[Unit]",
    "Description=nexis-next",
    "[Service]",
    "WorkingDirectory=/opt/nexis",
    "ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105",
    "Restart=always",
    "[Install]",
    "WantedBy=multi-user.target",
  ].join("\n");
  assert.deepEqual(parseUnitExecPaths(unit), [{ directive: "ExecStart", path: "/usr/local/bin/node" }]);
});

test("systemd's -, @, +, ! and !! prefixes are stripped in any combination", () => {
  const cases = ["-", "@", "+", "!", "!!", "-@", "+!", "!!-", "@+!"];
  for (const prefix of cases) {
    assert.deepEqual(
      parseUnitExecPaths(`ExecStart=${prefix}/usr/bin/sshd -D`),
      [{ directive: "ExecStart", path: "/usr/bin/sshd" }],
      `prefix ${prefix}`,
    );
  }
  // With whitespace after the prefix, as systemd also allows.
  assert.deepEqual(parseUnitExecPaths("ExecStart=- /usr/bin/sshd"), [{ directive: "ExecStart", path: "/usr/bin/sshd" }]);
});

test("quoted commands are unquoted; a path with a space is skipped as unresolvable", () => {
  assert.deepEqual(parseUnitExecPaths('ExecStart="/usr/bin/python3" /srv/app/main.py'), [
    { directive: "ExecStart", path: "/usr/bin/python3" },
  ]);
  assert.deepEqual(parseUnitExecPaths("ExecStart='/usr/bin/php8.2' -f /srv/cron.php"), [
    { directive: "ExecStart", path: "/usr/bin/php8.2" },
  ]);
  // Spaces are outside the shell-inert allowlist, so the path is reported to
  // nobody rather than being interpolated into a command.
  assert.deepEqual(parseUnitExecPaths('ExecStart="/opt/my app/bin/run" --flag'), []);
});

test("line continuations are folded before the command is read", () => {
  // Read line-at-a-time, the first line's command is empty and the check is
  // skipped entirely — the unit then gets enabled unverified.
  const unit = ["[Service]", "ExecStart=\\", "  /usr/local/bin/node \\", "  /opt/nexis/server.js --port 3105"].join("\n");
  assert.deepEqual(unfoldUnitLines(unit), ["[Service]", "ExecStart=   /usr/local/bin/node   /opt/nexis/server.js --port 3105"]);
  assert.deepEqual(parseUnitExecPaths(unit), [{ directive: "ExecStart", path: "/usr/local/bin/node" }]);
  // CRLF unit files (copied off a Windows-edited source) fold identically.
  assert.deepEqual(parseUnitExecPaths("ExecStart=\\\r\n  /usr/bin/node /app/x.js\r\n"), [
    { directive: "ExecStart", path: "/usr/bin/node" },
  ]);
});

test("% specifiers, PATH-relative commands and list resets are all skipped", () => {
  assert.deepEqual(parseUnitExecPaths("ExecStart=/usr/bin/%i --serve"), [], "%i can only be resolved by systemd");
  assert.deepEqual(parseUnitExecPaths("ExecStart=/opt/app/%n/run"), []);
  assert.deepEqual(parseUnitExecPaths("ExecStart=node /srv/server.js"), [], "PATH-resolved: not ours to check");
  assert.deepEqual(parseUnitExecPaths("ExecStart=env NODE_ENV=production node app.js"), []);
  assert.deepEqual(parseUnitExecPaths("ExecStart="), [], "an empty assignment is systemd's list reset");
  assert.deepEqual(parseUnitExecPaths("ExecStart=  "), []);
  assert.deepEqual(parseUnitExecPaths("ExecStart=-"), [], "a bare prefix with no command");
  assert.deepEqual(parseUnitExecPaths("ExecStart=../../bin/node app.js"), [], "relative paths are not absolute");
  assert.deepEqual(parseUnitExecPaths("ExecStart=/usr/bin/../bin/node"), [], ".. is rejected, never normalised");
});

test("only the three start directives are collected, and duplicates collapse", () => {
  const unit = [
    "[Service]",
    "ExecStartPre=/usr/bin/mkdir -p /run/app",
    "ExecStart=/usr/bin/node /srv/app.js",
    "ExecStartPost=/usr/bin/systemd-notify --ready",
    "ExecReload=/bin/kill -HUP $MAINPID",
    "ExecStop=/usr/bin/node /srv/shutdown.js",
    "ExecStopPost=/usr/bin/rm -f /run/app/pid",
  ].join("\n");
  assert.deepEqual(parseUnitExecPaths(unit), [
    { directive: "ExecStartPre", path: "/usr/bin/mkdir" },
    { directive: "ExecStart", path: "/usr/bin/node" },
    { directive: "ExecStartPost", path: "/usr/bin/systemd-notify" },
  ]);

  const dupes = ["ExecStartPre=/usr/bin/node /a.js", "ExecStartPre=/usr/bin/node /b.js", "ExecStart=/usr/bin/node /c.js"].join("\n");
  assert.deepEqual(parseUnitExecPaths(dupes), [
    { directive: "ExecStartPre", path: "/usr/bin/node" },
    { directive: "ExecStart", path: "/usr/bin/node" },
  ], "same directive + same path once; a different directive is its own check");
});

test("a pathological unit cannot make the pre-flight unbounded", () => {
  const many = Array.from({ length: 40 }, (_, i) => `ExecStartPre=/usr/bin/tool${i}`).join("\n");
  assert.equal(parseUnitExecPaths(many).length, 12, "capped at 12 exec refs");
  assert.deepEqual(parseUnitExecPaths(""), []);
  assert.deepEqual(parseUnitExecPaths("[Unit]\nDescription=nothing to run here\n"), []);
});

/* ------------------------------------------------------------------ *
 * 4. The exec pre-flight ladder, driven through UnitExecHost
 * ------------------------------------------------------------------ */

type FakeHostOpts = {
  unitText: string;
  /** Absolute paths that exist AND are executable on the target. */
  executable?: string[];
  /** Absolute paths that exist but are not executable. */
  presentNotExecutable?: string[];
  /** basename -> what `command -v` answers. */
  which?: Record<string, string>;
  /** Absolute paths that exist on the SOURCE box. */
  onSource?: string[];
  /** Make symlink creation fail (read-only /usr, race, …). */
  symlinkFails?: boolean;
  copyFails?: boolean;
};

function fakeHost(opts: FakeHostOpts) {
  const executable = new Set(opts.executable ?? []);
  const present = new Set([...(opts.presentNotExecutable ?? []), ...executable]);
  const calls: string[] = [];
  const host: UnitExecHost = {
    readUnitFile: async () => opts.unitText,
    isExecutable: async (p) => executable.has(p),
    exists: async (p) => present.has(p),
    whichSameName: async (base) => opts.which?.[base] ?? "",
    symlink: async ({ target, linkPath }) => {
      calls.push(`symlink ${linkPath} -> ${target}`);
      if (opts.symlinkFails) return false;
      executable.add(linkPath);
      present.add(linkPath);
      return true;
    },
  };
  const said: string[] = [];
  return {
    host,
    calls,
    said,
    args: {
      host,
      unit: "nexis-next",
      unitFile: "/etc/systemd/system/nexis-next.service",
      existsOnSource: async (p: string) => (opts.onSource ?? []).includes(p),
      copyFromSource: async (p: string) => {
        calls.push(`copy ${p}`);
        if (opts.copyFails) return false;
        executable.add(p);
        present.add(p);
        return true;
      },
      say: async (line: string) => {
        said.push(line);
      },
    },
  };
}

const INCIDENT_UNIT = "[Service]\nExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105\n";

test("the same program under a different prefix is symlinked, not guessed at", async () => {
  // /usr/local/bin/node missing, apt's /usr/bin/node present: exactly incident #25.
  const f = fakeHost({
    unitText: INCIDENT_UNIT,
    executable: ["/usr/bin/node"],
    which: { node: "/usr/bin/node" },
  });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, true);
  assert.deepEqual(r.blockers, []);
  assert.equal(r.repairs.length, 1);
  assert.match(r.repairs[0], /\/usr\/local\/bin\/node/);
  assert.match(r.repairs[0], /linked it to \/usr\/bin\/node/);
  assert.deepEqual(f.calls, ["symlink /usr/local/bin/node -> /usr/bin/node"]);
  assert.equal(f.said.length, 1, "the customer-visible log says what was done");
});

test("an exec that is already runnable is left completely alone", async () => {
  const f = fakeHost({ unitText: INCIDENT_UNIT, executable: ["/usr/local/bin/node", "/usr/bin/node"] });
  const r = await preflightUnitExecs(f.args);
  assert.deepEqual(r, { ok: true, repairs: [], blockers: [] });
  assert.deepEqual(f.calls, [], "no symlink, no copy");
});

test("present-but-not-executable is reported with the chmod, never silently chmod-ed", async () => {
  const f = fakeHost({
    unitText: INCIDENT_UNIT,
    presentNotExecutable: ["/usr/local/bin/node"],
    which: { node: "/usr/bin/node" },
    executable: ["/usr/bin/node"],
  });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, false);
  assert.equal(r.blockers.length, 1);
  assert.equal(r.blockers[0].domain, "nexis-next.service");
  assert.match(r.blockers[0].why, /not executable/);
  assert.match(r.blockers[0].why, /203\/EXEC/);
  assert.match(r.blockers[0].fix, /^chmod \+x \/usr\/local\/bin\/node/);
  assert.deepEqual(f.calls, [], "changing the mode of the customer's file is their call");
});

test("a binary that exists only on the source is copied across", async () => {
  const f = fakeHost({ unitText: INCIDENT_UNIT, onSource: ["/usr/local/bin/node"] });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, true);
  assert.match(r.repairs[0], /copied \/usr\/local\/bin\/node from the old server/);
  assert.deepEqual(f.calls, ["copy /usr/local/bin/node"]);
});

test("when nothing can be resolved the unit BLOCKS with the exact path and a fix", async () => {
  // The failure the gate exists for: without this the unit is enabled, fails
  // 203/EXEC, restarts forever, and the migration reports success.
  const f = fakeHost({ unitText: INCIDENT_UNIT });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, false);
  assert.deepEqual(r.repairs, []);
  assert.equal(r.blockers.length, 1);
  assert.match(r.blockers[0].why, /\/usr\/local\/bin\/node/);
  assert.match(r.blockers[0].why, /203\/EXEC/);
  assert.match(r.blockers[0].fix, /ln -s "\$\(command -v node\)" \/usr\/local\/bin\/node/);
  assert.match(r.blockers[0].fix, /systemctl daemon-reload && systemctl restart nexis-next/);
});

test("a failed repair blocks rather than reporting a repair that did not happen", async () => {
  const linkFails = fakeHost({
    unitText: INCIDENT_UNIT,
    executable: ["/usr/bin/node"],
    which: { node: "/usr/bin/node" },
    symlinkFails: true,
  });
  const a = await preflightUnitExecs(linkFails.args);
  assert.equal(a.ok, false);
  assert.deepEqual(a.repairs, []);

  const copyFails = fakeHost({ unitText: INCIDENT_UNIT, onSource: ["/usr/local/bin/node"], copyFails: true });
  const b = await preflightUnitExecs(copyFails.args);
  assert.equal(b.ok, false);
  assert.deepEqual(b.repairs, []);
  assert.equal(b.blockers.length, 1);
});

test("`command -v` answering with the very path we already know is missing is not a repair", async () => {
  // A stale shell hash or a same-path answer must not produce a self-symlink.
  const f = fakeHost({ unitText: INCIDENT_UNIT, which: { node: "/usr/local/bin/node" } });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, false);
  assert.deepEqual(f.calls, []);
});

test("every exec ref in a multi-directive unit is checked independently", async () => {
  const f = fakeHost({
    unitText: [
      "[Service]",
      "ExecStartPre=/usr/local/bin/prepare-app",
      "ExecStart=/usr/local/bin/node /srv/app.js",
      "ExecStartPost=/usr/bin/systemd-notify --ready",
    ].join("\n"),
    executable: ["/usr/bin/node", "/usr/bin/systemd-notify"],
    which: { node: "/usr/bin/node" },
  });
  const r = await preflightUnitExecs(f.args);
  assert.equal(r.ok, false, "prepare-app cannot be resolved");
  assert.equal(r.repairs.length, 1, "node was linked");
  assert.equal(r.blockers.length, 1, "prepare-app blocks");
  assert.match(r.blockers[0].why, /prepare-app/);
});

test("a unit name or path outside the allowlist is a safe no-op, never a shell risk", async () => {
  const f = fakeHost({ unitText: INCIDENT_UNIT });
  const bad = await preflightUnitExecs({ ...f.args, unit: "evil; rm -rf /" });
  assert.deepEqual(bad, { ok: true, repairs: [], blockers: [] });
  const badPath = await preflightUnitExecs({ ...f.args, unitFile: "/etc/systemd/system/$(id).service" });
  assert.deepEqual(badPath, { ok: true, repairs: [], blockers: [] });
});

test("an unreadable unit file yields nothing to check", async () => {
  const f = fakeHost({ unitText: "" });
  assert.deepEqual(await preflightUnitExecs(f.args), { ok: true, repairs: [], blockers: [] });
});

/* ------------------------------------------------------------------ *
 * 5. The outcome score
 *    Incident: the run log read "Sites actually serving: 4/4" while six of the
 *    customer's domains were dark, because the denominator was the set of names
 *    WE chose to publish rather than the set the old server answered on. And the
 *    result card said "Migration complete" for a run with issues.
 * ------------------------------------------------------------------ */

test("the score is measured against the SOURCE's domains, not the ones we probed", () => {
  const sourceDomains = ["a.com", "b.com", "c.com", "d.com", "e.com", "f.com"];
  const probeNames = ["a.com", "b.com", "c.com", "d.com"];
  const s = judgeMigrationOutcome({
    sourceDomains,
    probeNames,
    siteProbes: probeNames.map((domain) => ({ domain, serving: true })),
    unitBlockers: [],
  });
  assert.equal(s.outcome, "COMPLETED_WITH_ISSUES", "4 of 6 serving is not a completed migration");
  assert.deepEqual(s.scoredAgainst, sourceDomains);
  assert.equal(s.servingCount, 4);
  assert.deepEqual(s.unservedDomains, ["e.com", "f.com"]);
  assert.deepEqual(s.uncheckedDomains, ["e.com", "f.com"]);
  assert.deepEqual(s.failedProbe, [], "'we did not check' is reported separately from 'it is broken'");
  assert.equal(s.outcomeReasons.length, 1);
  assert.match(s.outcomeReasons[0], /were not checked at all/);
});

test("a domain that was probed and failed is named as broken", () => {
  const s = judgeMigrationOutcome({
    sourceDomains: ["studionexis.com", "www.studionexis.com"],
    probeNames: ["studionexis.com", "www.studionexis.com"],
    siteProbes: [
      { domain: "studionexis.com", serving: false },
      { domain: "www.studionexis.com", serving: true },
    ],
    unitBlockers: [],
  });
  assert.equal(s.outcome, "COMPLETED_WITH_ISSUES");
  assert.deepEqual(s.failedProbe, ["studionexis.com"]);
  assert.deepEqual(s.uncheckedDomains, []);
  assert.equal(s.servingCount, 1);
  assert.match(s.outcomeReasons[0], /does not serve here: studionexis\.com/);
});

test("COMPLETED requires every source domain serving AND every unit healthy", () => {
  const clean = judgeMigrationOutcome({
    sourceDomains: ["a.com", "b.com"],
    probeNames: ["a.com", "b.com"],
    siteProbes: [
      { domain: "a.com", serving: true },
      { domain: "b.com", serving: true },
    ],
    unitBlockers: [],
  });
  assert.equal(clean.outcome, "COMPLETED");
  assert.deepEqual(clean.outcomeReasons, []);
  assert.equal(clean.servingCount, 2);

  // Same domains, but a migrated unit is crash-looping (the 78-restart incident).
  const withUnit = judgeMigrationOutcome({
    sourceDomains: ["a.com", "b.com"],
    probeNames: ["a.com", "b.com"],
    siteProbes: [
      { domain: "a.com", serving: true },
      { domain: "b.com", serving: true },
    ],
    unitBlockers: [{ domain: "nexis-next.service" }],
  });
  assert.equal(withUnit.outcome, "COMPLETED_WITH_ISSUES");
  assert.match(withUnit.outcomeReasons[0], /nexis-next\.service/);
  assert.match(withUnit.outcomeReasons[0], /not running/);
});

test("an unreadable source inventory can never be scored as a clean run", () => {
  // No denominator of our own choosing may produce a green result: falling back to
  // the names we published is itself an outcome reason.
  const s = judgeMigrationOutcome({
    sourceDomains: [],
    probeNames: ["a.com"],
    siteProbes: [{ domain: "a.com", serving: true }],
    unitBlockers: [],
  });
  assert.equal(s.outcome, "COMPLETED_WITH_ISSUES");
  assert.deepEqual(s.scoredAgainst, ["a.com"]);
  assert.equal(s.servingCount, 1);
  assert.match(s.outcomeReasons[0], /could not be read/);
});

test("nothing to migrate is not an issue", () => {
  const s = judgeMigrationOutcome({ sourceDomains: [], probeNames: [], siteProbes: [], unitBlockers: [] });
  assert.equal(s.outcome, "COMPLETED");
  assert.deepEqual(s.outcomeReasons, []);
});

test("long failure lists are truncated but the count is always exact", () => {
  const sourceDomains = Array.from({ length: 12 }, (_, i) => `d${i}.com`);
  const s = judgeMigrationOutcome({
    sourceDomains,
    probeNames: sourceDomains,
    siteProbes: sourceDomains.map((domain) => ({ domain, serving: false })),
    unitBlockers: [],
  });
  assert.equal(s.failedProbe.length, 12, "the list itself is complete");
  assert.match(s.outcomeReasons[0], /^12 of the 12 domain\(s\)/);
  assert.match(s.outcomeReasons[0], / …$/, "only the rendered sample is capped");
});

