import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { parseSizeLabel, syntheticScan } from "../worker/migrate-detect.ts";

/**
 * REAL INCIDENT — the storage pre-flight double-count (2026-07-25, commit
 * 05e6605; postmortem in docs/DOCUMENTATION.md, audit rec #16).
 *
 * `lib/actions-migrate.ts` added the Docker image allowance into
 * `items.totalBytes`, but `worker/migrate-real.ts` reads that value as
 * `fileBytes` and adds the Docker allowance ITSELF. A ~12 GB move was therefore
 * reported as needing 83.6 GB and refused — and the inflated figure led the owner
 * to buy ~40 GB of disk that was not needed. Disk growth is one-way, so that
 * spend is unrecoverable. The audit: this "would have been caught by one
 * assertion that the wizard and engine agree".
 *
 * That assertion is `the wizard's Docker allowance is the engine's Docker
 * allowance` below. The arithmetic itself lives inside a `"use server"` module
 * (`selectedMigrationBytes`, not exported) and inside a `useMemo` in a React
 * component, so neither can be imported here; the pieces that CAN be imported are
 * exercised directly, and the two formulas are cross-checked against the real
 * source text so a change on either side fails this file.
 *
 * Deterministic: no SSH, no scan, no clock — `syntheticScan` is the repo's own
 * fixed sandbox fixture.
 */

const REPO = join(__dirname, "..");
const GiB = 1024 ** 3;

const WORKER_SRC = readFileSync(join(REPO, "worker/migrate-real.ts"), "utf8");
const WIZARD_SRC = readFileSync(join(REPO, "components/customer/MigrationWizard.tsx"), "utf8");
const ACTIONS_SRC = readFileSync(join(REPO, "lib/actions-migrate.ts"), "utf8");

/** Pull a numeric constant out of a source file, failing loudly if it moved. */
function sourceNumber(src: string, re: RegExp, what: string): number {
  const m = re.exec(src);
  assert.ok(m, `${what}: could not find ${re} — the formula moved, re-read it and update this test`);
  return Number(m![1]);
}

/* ------------------------------------------------------------------ *
 * The two allowances, read from the code that actually runs
 * ------------------------------------------------------------------ */

/** worker/migrate-real.ts: `const IMAGE_OVERHEAD_FACTOR = 2;` */
const ENGINE_IMAGE_FACTOR = sourceNumber(
  WORKER_SRC,
  /const IMAGE_OVERHEAD_FACTOR = (\d+(?:\.\d+)?);/,
  "engine image overhead",
);
/** worker/migrate-real.ts: `const FS_HEADROOM = 2 * GiB;` */
const ENGINE_HEADROOM_GIB = sourceNumber(WORKER_SRC, /const FS_HEADROOM = (\d+(?:\.\d+)?) \* GiB;/, "engine headroom");
/** MigrationWizard.tsx: `const d = imageBytes > 0 ? imageBytes * 2 + 2 * GiB : 0;` */
const WIZARD_DOCKER_RE = /const d = imageBytes > 0 \? imageBytes \* (\d+(?:\.\d+)?) \+ (\d+(?:\.\d+)?) \* GiB : 0;/;

test("the wizard's Docker allowance is the engine's Docker allowance", () => {
  // THE assertion the audit asked for. If either side changes its factor or its
  // headroom, the customer is shown a number the engine will not honour — which is
  // how a 12 GB move came to be quoted at 83.6 GB.
  const m = WIZARD_DOCKER_RE.exec(WIZARD_SRC);
  assert.ok(m, "the wizard's Docker allowance line moved — re-check it against worker/migrate-real.ts");
  assert.equal(Number(m![1]), ENGINE_IMAGE_FACTOR, "image unpack factor: wizard vs engine");
  assert.equal(Number(m![2]), ENGINE_HEADROOM_GIB, "working headroom: wizard vs engine");
  assert.equal(ENGINE_IMAGE_FACTOR, 2);
  assert.equal(ENGINE_HEADROOM_GIB, 2);
});

/* ------------------------------------------------------------------ *
 * The arithmetic, with the incident's own numbers
 * ------------------------------------------------------------------ */

/** worker/migrate-real.ts:3468-3470 — `items.totalBytes` is read as fileBytes. */
function engineRequiredBytes(opts: { totalBytesFromItems: number; imageBytes: number; volumeBytes: number }): number {
  const fileBytes = Math.max(0, Number(opts.totalBytesFromItems ?? 0));
  const dockerBytes = opts.imageBytes * ENGINE_IMAGE_FACTOR + opts.volumeBytes;
  return fileBytes + dockerBytes + ENGINE_HEADROOM_GIB * GiB;
}

/** MigrationWizard.tsx:379-391 — what the customer is shown as the move's size. */
function wizardTotalBytes(opts: { fileBytes: number; imageBytes: number }): number {
  const imageBytes = Math.max(0, opts.imageBytes);
  const d = imageBytes > 0 ? imageBytes * 2 + 2 * GiB : 0;
  return opts.fileBytes + d;
}

test("a 12 GB move needs 48.8 GB — the 83.6 GB refusal was the Docker bytes counted twice", () => {
  const fileBytes = 12 * GiB;
  const imageBytes = 17.4 * GiB;
  const dockerBytes = imageBytes * ENGINE_IMAGE_FACTOR;

  const correct = engineRequiredBytes({ totalBytesFromItems: fileBytes, imageBytes, volumeBytes: 0 });
  assert.equal(correct / GiB, 48.8, "files-only total in items.totalBytes");

  // The bug: items.totalBytes arrived with Docker already inside it.
  const doubleCounted = engineRequiredBytes({
    totalBytesFromItems: fileBytes + dockerBytes,
    imageBytes,
    volumeBytes: 0,
  });
  assert.equal(doubleCounted / GiB, 83.6, "the exact figure the customer was refused with");
  assert.equal(doubleCounted - correct, dockerBytes, "the overage is precisely one Docker allowance");
});

test("the size the wizard displays equals the space the engine demands", () => {
  // Same inputs, both formulas: the panel that says "will it fit?" and the
  // pre-flight that can refuse must produce one number.
  for (const fileGiB of [0, 0.5, 12, 40]) {
    for (const imageGiB of [0, 1.6, 17.4]) {
      const shown = wizardTotalBytes({ fileBytes: fileGiB * GiB, imageBytes: imageGiB * GiB });
      const required = engineRequiredBytes({
        totalBytesFromItems: fileGiB * GiB,
        imageBytes: imageGiB * GiB,
        volumeBytes: 0,
      });
      if (imageGiB > 0) {
        assert.equal(shown, required, `${fileGiB} GiB files + ${imageGiB} GiB images`);
      } else {
        // With no Docker at all the wizard shows the file bytes alone and accounts
        // for headroom through its own display margin instead.
        assert.equal(shown, fileGiB * GiB);
        assert.equal(required - shown, ENGINE_HEADROOM_GIB * GiB);
      }
    }
  }
});

/* ------------------------------------------------------------------ *
 * The files-only contract, at both ends
 * ------------------------------------------------------------------ */

test("the stored total is FILES ONLY — selected paths plus the DB data dir", () => {
  // Reproduces the shape of lib/actions-migrate.ts selectedMigrationBytes over the
  // repo's own sandbox fixture: sizes come from the scan's human labels, databases
  // are auto-included when an engine is present, and Docker is NOT in here.
  const scan = syntheticScan({ dbPassword: undefined });
  const sizeByPath = new Map<string, number>();
  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
  let total = 0;
