/* ------------------------------------------------------------------ *
 * parseSizeLabel — the building block of every file estimate
 * ------------------------------------------------------------------ */

test("parseSizeLabel reads every label shape the scan produces", () => {
  assert.equal(parseSizeLabel("1.2 GB"), 1.2 * GiB);
  assert.equal(parseSizeLabel("1.2G"), 1.2 * GiB);
  assert.equal(parseSizeLabel("340 MB"), 340 * 1024 ** 2);
  assert.equal(parseSizeLabel("340M"), 340 * 1024 ** 2);
  assert.equal(parseSizeLabel("512K"), 512 * 1024);
  assert.equal(parseSizeLabel("2T"), 2 * 1024 ** 4);
