import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { DUNNING_RETRY_ATTEMPTS, emails } from "../lib/mailer.ts";

/**
 * REAL INCIDENT / REAL RISK — the dunning ladder (audit gaps #3 and #9, QA P1-5).
 *
 * Before the card engine existed, a customer with a perfectly good card was
 * suspended the moment their wallet emptied, and was told about it with nothing
 * but a bell icon in a portal they had stopped visiting. The replacement retries
 * the card on days 1, 3 and 5 past expiry, emails at each step, and suspends only
 * after every attempt is spent PLUS one clear day after the final notice.
 *
 * Two things can silently break that promise:
 *   (a) the schedule the worker runs drifting from the number the email quotes
 *       ("we'll try 2 more times" when only one attempt is left), and
 *   (b) a suspension landing on or before the day of the final notice, so the
 *       warning arrives after the server is already down.
 *
 * The worker derives the whole ladder from `DUNNING_RETRY_ATTEMPTS` in
 * lib/mailer.ts — the same constant the email copy subtracts from — precisely so
 * they cannot drift. That derivation is module-private in `worker/billing.ts`
 * (and duplicated by hand in `lib/actions-settings.ts`), so this file reads the
 * constants out of the source and holds them against the imported constant and
 * against the actual rendered email text.
 *
 * Deterministic: everything is arithmetic on day offsets. No clock, no DB, no
 * Stripe — the email builders are pure and send nothing.
 */

const REPO = join(__dirname, "..");
const BILLING_SRC = readFileSync(join(REPO, "worker/billing.ts"), "utf8");
const SETTINGS_SRC = readFileSync(join(REPO, "lib/actions-settings.ts"), "utf8");

function sourceNumber(src: string, re: RegExp, what: string): number {
  const m = re.exec(src);
  assert.ok(m, `${what}: ${re} not found — the dunning ladder was rewritten, re-read it and update this test`);
  return Number(m![1]);
}

/* ---- the ladder, read from worker/billing.ts ---------------------------- */

/** `const retryDayFor = (retry: number) => 2 * retry - 1;` */
const RETRY_DAY_MULT = sourceNumber(BILLING_SRC, /const retryDayFor = \(retry: number\) => (\d+) \* retry - \d+;/, "retryDayFor multiplier");
const RETRY_DAY_OFFSET = sourceNumber(BILLING_SRC, /const retryDayFor = \(retry: number\) => \d+ \* retry - (\d+);/, "retryDayFor offset");
const retryDayFor = (retry: number) => RETRY_DAY_MULT * retry - RETRY_DAY_OFFSET;

/** `const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;` */
const SUSPEND_DAYS_AFTER_LAST_RETRY = sourceNumber(BILLING_SRC, /const CARD_SUSPEND_DAY = LAST_RETRY_DAY \+ (\d+);/, "CARD_SUSPEND_DAY");
/** `const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;` */
const EXHAUSTED_OFFSET = sourceNumber(BILLING_SRC, /const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS \+ (\d+);/, "DUNNING_EXHAUSTED");
/** `const SUSPEND_SLIP_CAP_DAYS = 4;` */
const SUSPEND_SLIP_CAP_DAYS = sourceNumber(BILLING_SRC, /const SUSPEND_SLIP_CAP_DAYS = (\d+);/, "SUSPEND_SLIP_CAP_DAYS");
/** `const MIN_RETRY_GAP_MS = 20 * 3600_000;` */
const MIN_RETRY_GAP_HOURS = sourceNumber(BILLING_SRC, /const MIN_RETRY_GAP_MS = (\d+) \* 3600_000;/, "MIN_RETRY_GAP_MS");

/** Days past expiry on which the worker retries the card. */
const RETRY_DAYS = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) => retryDayFor(i + 1));
const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + EXHAUSTED_OFFSET;

test("the ladder is the documented day-1/3/5 schedule", () => {
  assert.equal(DUNNING_RETRY_ATTEMPTS, 3);
  assert.deepEqual(RETRY_DAYS, [1, 3, 5]);
  assert.equal(LAST_RETRY_DAY, 5);
  assert.equal(CARD_SUSPEND_DAY, 6);
  assert.equal(DUNNING_EXHAUSTED, 4, "the expiry-day attempt plus three retries");
});

test("the schedule is DERIVED from DUNNING_RETRY_ATTEMPTS, not hardcoded beside it", () => {
  // The one line that keeps the worker's behaviour and the email's promise tied
  // together. A literal here is how "we'll try 3 more times" starts outliving the
  // third retry.
  assert.ok(
    BILLING_SRC.includes("const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);"),
    "the last retry day must be derived from the constant the emails quote",
  );
  assert.ok(BILLING_SRC.includes("const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;"));
  assert.ok(
    BILLING_SRC.includes('import { DUNNING_RETRY_ATTEMPTS, emails, sendMail } from "../lib/mailer";'),
    "one constant, imported — not a second copy of the number",
  );
});

test("one retry per attempt, strictly increasing, never before expiry", () => {
  assert.equal(RETRY_DAYS.length, DUNNING_RETRY_ATTEMPTS, "as many retry slots as attempts promised");
  assert.equal(new Set(RETRY_DAYS).size, RETRY_DAYS.length, "no two retries on the same day");
  for (let i = 0; i < RETRY_DAYS.length; i++) {
    assert.ok(RETRY_DAYS[i] >= 1, `retry ${i + 1} must land at least a day past expiry, got ${RETRY_DAYS[i]}`);
    if (i > 0) assert.ok(RETRY_DAYS[i] > RETRY_DAYS[i - 1], "the ladder must move forward");
  }
});

test("suspension never precedes the final notice", () => {
  // The final notice is sent when the LAST retry fails, i.e. on LAST_RETRY_DAY.
  // Suspension must be strictly later, with at least one clear day in between.
  assert.ok(
    CARD_SUSPEND_DAY > LAST_RETRY_DAY,
    `suspension day ${CARD_SUSPEND_DAY} must be after the final notice on day ${LAST_RETRY_DAY}`,
  );
  assert.ok(SUSPEND_DAYS_AFTER_LAST_RETRY >= 1, "at least one clear day with the warning in hand");
  // And every retry the customer was promised happens BEFORE the suspension.
  for (const day of RETRY_DAYS) assert.ok(day < CARD_SUSPEND_DAY, `retry on day ${day} must precede suspension`);
});

test("the email quotes exactly the number of retries that are actually left", () => {
  // `recordDeclinedAttempt` calls paymentRetryFailed with attempt = newStage - 1,
  // so attempt N is the failure of the Nth retry (the day-N entry of RETRY_DAYS).
  // The copy must promise only the retries that come after it.
  for (let attempt = 1; attempt <= DUNNING_RETRY_ATTEMPTS; attempt++) {
    const stillToCome = RETRY_DAYS.filter((d) => d > RETRY_DAYS[attempt - 1]).length;
    const built = emails.paymentRetryFailed("web-01", "$12.99", attempt, "August 1, 2026", "https://x.test/billing");
    if (stillToCome === 1) {
      assert.match(built.html, /try 1 more time\b/, `attempt ${attempt}: one retry left`);
    } else if (stillToCome > 1) {
      assert.match(built.html, new RegExp(`try ${stillToCome} more times`), `attempt ${attempt}`);
    } else {
      assert.match(built.html, /last automatic attempt/, `attempt ${attempt}: nothing left to promise`);
    }
    // Whatever the count, the email must never claim the server is already down.
    assert.match(built.subject, /still running until August 1, 2026/);
  }
});

test("the retry emails are numbered and the final notice promises nothing further", () => {
  const second = emails.paymentRetryFailed("web-01", "$12.99", 2, "August 1, 2026", "https://x.test/billing");
  assert.match(second.subject, /^Payment retry 2 declined for web-01/);
  assert.equal(second.template, "payment_retry_failed");

  const final = emails.paymentFinalNotice("web-01", "$12.99", "https://x.test/billing");
  assert.equal(final.template, "payment_final_notice");
  assert.match(final.subject, /^Final notice for web-01/);
  assert.match(final.html, /run out of automatic attempts/);
  assert.doesNotMatch(final.html, /we'll try \d+ more time/i, "the final notice must not promise another attempt");
  // It is sent while the server is still UP — suspension is a day away.
  assert.match(final.html, /still running/i);
  assert.match(final.html, /nothing is deleted/i);

  // The first decline (expiry day) names the day-1 retry it is about to make.
  const first = emails.paymentFailed("web-01", "$12.99", "4242", "July 27, 2026", "https://x.test/billing");
  assert.equal(first.template, "payment_failed");
  assert.match(first.subject, /we'll retry July 27, 2026/);
});

test("the minimum retry gap cannot compress or delay the promised ladder", () => {
  // A worker that was down for a week must not discover four overdue slots and
  // fire the whole sequence — three charges and three emails — in one afternoon.
  const sweepIntervalHours = 10 / 60;
  const smallestLadderGapHours = Math.min(...RETRY_DAYS.slice(1).map((d, i) => (d - RETRY_DAYS[i]) * 24));
  assert.ok(MIN_RETRY_GAP_HOURS > sweepIntervalHours * 10, "a backlog must not burn the ladder in one pass");
  assert.ok(
    MIN_RETRY_GAP_HOURS < smallestLadderGapHours,
    `a ${MIN_RETRY_GAP_HOURS}h floor must not push out the normal ${smallestLadderGapHours}h gap`,
  );
});

test("termination is always after the latest suspension the sequence can reach", () => {
  // A late-starting sequence can slip the suspension by SUSPEND_SLIP_CAP_DAYS, so
  // the terminate floor has to clear that, or the sweep could destroy a VM on (or
  // before) the day it was paused. dunningConfig() enforces this at runtime.
  const defaultGraceDays = 3;
  const latestSuspendDay = Math.max(defaultGraceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);
  const terminateFloor = latestSuspendDay + 1;
  assert.equal(latestSuspendDay, 10);
  assert.equal(terminateFloor, 11);
  assert.ok(
    BILLING_SRC.includes("const latestSuspendDay = Math.max(graceDays, CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS);") &&
      BILLING_SRC.includes("terminateDays = Math.max(terminateDays, latestSuspendDay + 1);"),
    "the runtime clamp must keep termination after suspension",
  );
  // …and the deletion warning always lands before the deletion it warns about.
  assert.ok(BILLING_SRC.includes("warnDays = Math.min(Math.max(warnDays, 1), terminateDays - 1);"));
});

test("the admin panel's terminate floor matches the worker's arithmetic", () => {
  // lib/actions-settings.ts states this number by hand ("duplicated deliberately
  // and named so it is greppable if the retry schedule changes") so that the panel
  // cannot display a termination day earlier than the worker will honour. This is
  // the test that notices when the schedule changes and the copy does not.
  const panelFloor = sourceNumber(SETTINGS_SRC, /const MIN_TERMINATE_DAYS = (\d+);/, "MIN_TERMINATE_DAYS");
  assert.equal(
    panelFloor,
    CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS + 1,
    "MIN_TERMINATE_DAYS in lib/actions-settings.ts no longer matches worker/billing.ts",
  );
});

test("a re-armed attempt after the sequence is spent cannot send a second final notice", () => {
  // `recordDeclinedAttempt` clamps the stage at DUNNING_EXHAUSTED and returns early
  // when it was already there, so a customer who saves a new card that also fails
  // gets no duplicate final notice and no further deferral of the suspension.
  assert.ok(BILLING_SRC.includes("const newStage = Math.min(prevStage + 1, DUNNING_EXHAUSTED);"));
  assert.ok(BILLING_SRC.includes("if (prevStage >= DUNNING_EXHAUSTED) {"));
  assert.ok(
    BILLING_SRC.includes("if (failures >= DUNNING_EXHAUSTED) return null;"),
    "no retry slot exists past the last one",
  );
});

