import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {

/**
 * TRIPWIRE on the four call sites — QA-PRELAUNCH P1-15: "ResizeDown's displayed
 * credit uses a third, different formula from the server". For Max -> Standard
 * with 364 days left the customer was SHOWN $215.41 and CREDITED $239.16. Both
 * pickers are React components that cannot be imported here, so this checks that
 * each display path and its server path still call the same shared function with
 * the same arguments.
 */
const readNormalized = (rel: string) => readFileSync(join(__dirname, "..", rel), "utf8").replace(/\s+/g, " ");

test("both resize directions price through lib/proration.ts, client and server alike", () => {
  const pairs: [string, string, string][] = [
    ["lib/resize.ts", "components/customer/ResizePicker.tsx", "prorateUpgradeCents"],
    ["lib/actions-server-lifecycle.ts", "components/customer/ResizeDown.tsx", "prorateDowngradeCreditCents"],
  ];
  for (const [serverFile, clientFile, fn] of pairs) {
    for (const file of [serverFile, clientFile]) {
      const src = readNormalized(file);
      assert.ok(src.includes(fn), `${file} must price through ${fn}, not a local reimplementation`);
      assert.ok(src.includes("remainingMonths("), `${file} must use the shared remainingMonths`);
      assert.ok(
        !/priceCents - [a-zA-Z.]*plan\.priceCents/.test(src),
        `${file} looks like it computes a raw list-price delta again`,
      );
    }
  }
});

test("each direction's client and server agree on the remaining-term cap", () => {
  // The credit side clamps to one term (an unclamped credit refunded months the
  // customer never paid for); the charge side does not. What matters here is that
  // the picker and the action on EACH side pass the same thing — the up-vs-down
  // asymmetry itself is reported separately, not asserted as correct.
  const upServer = readNormalized("lib/resize.ts");
  const upClient = readNormalized("components/customer/ResizePicker.tsx");
  assert.ok(upServer.includes("remainingMonths(server.expiresAt, Date.now())"), "upgrade server: uncapped");
  assert.ok(upClient.includes("remainingMonths(new Date(expiresAt), Date.now())"), "upgrade client: uncapped");

  const downServer = readNormalized("lib/actions-server-lifecycle.ts");
  const downClient = readNormalized("components/customer/ResizeDown.tsx");
  assert.ok(
    downServer.includes("remainingMonths(server.expiresAt, Date.now(), server.termMonths)"),
    "downgrade server: capped at one term",
  );
  assert.ok(
    downClient.includes("remainingMonths(new Date(expiresAt), Date.now(), termMonths)"),
    "downgrade client: capped at one term",
  );
});

